			/*
			 * 그리드에서 selection-change 이벤트 발생 시 호출.
			 * detail의 cell 클릭하여 설정된 selectionunit에 해당되는 단위가 선택될 때 발생하는 이벤트.
			 */
			function onGrd1SelectionChange(e){
			    var grd1 = e.control;
			    
			    moDate = {};
			    
			    console.log("나의 위치는 여기다 ::: " + grd1.getSelectedRowIndex());
			    
			    var dsMonthWorkTime = app.lookup("dsMonthWorkTime");
			    var vsStrTime = dsMonthWorkTime.getValue(grd1.getSelectedRowIndex(), "BGNG_HR");
			    console.log("vsStrTime ::: " +vsStrTime);
			    var vsStrMin = dsMonthWorkTime.getValue(grd1.getSelectedRowIndex(), "BGNG_MIN");
			    console.log("vsStrMin ::: " +vsStrMin);
			    var vsEndTime = dsMonthWorkTime.getValue(grd1.getSelectedRowIndex(), "END_HR");
			    console.log("vsEndTime ::: " +vsEndTime);
			    var vsEndMin = dsMonthWorkTime.getValue(grd1.getSelectedRowIndex(), "END_MIN");
			    console.log("vsEndMin ::: " +vsEndMin);
			    
			    if (vsStrTime != null && vsStrTime != "") {
			        moDate["strTime"] = vsStrTime;
			        moBeforeStrDate = moBeforeStrDate.hour(vsStrTime);
			        moStrDate = moStrDate.hour(vsStrTime);
			    }
			    
			    if (vsStrMin != null && vsStrMin != "") {
			        moDate["strMin"] = vsStrMin;
			        moBeforeStrDate = moBeforeStrDate.minute(vsStrMin);
			        moStrDate = moStrDate.minute(vsStrMin);
			    }
			    
			    if (vsEndTime != null && vsEndTime != "") {
			        
			        moDate["endTime"] = vsEndTime;
			        moBeforeEndDate = moBeforeEndDate.hour(vsEndTime);
			        moEndDate = moEndDate.hour(vsEndTime);
			        
			        // 시작시간과 종료시간을 비교하는 로직에 의해 생긴 문제(시작시간 = 20:30 / 종료시간 = 00:30을 선택할 경우 함수 beforeCheckTime에서 return false가 떨어진다.) 해결 로직
			        if (moBeforeStrDate.format("HH") >= "20" && moBeforeEndDate.format("HH") <= "06") {
			            
			            if (moBeforeStrDate.format("YYYYMMDD") == moBeforeEndDate.format("YYYYMMDD")) {
			        
			                moBeforeEndDate.add(1, "day");
			                moEndDate.add(1, "day");
			                console.log("변경 후 : " + moBeforeEndDate.format("YYYYMMDDHHmm"));
			                
			            } 
			            
			        } else {
			            
			            if (moBeforeStrDate.format("YYYYMMDD") < moBeforeEndDate.format("YYYYMMDD")) {
			                moBeforeEndDate.add(-1, "day");
			                moEndDate.add(-1, "day");
			                console.log("변경 후 : " + moBeforeEndDate.format("YYYYMMDDHHmm"));
			            }
			            
			        }
			        
			    }
			    
			    if (vsEndMin != null && vsEndMin != "") {
			        moDate["endMin"] = vsEndMin;
			        moBeforeEndDate = moBeforeEndDate.minute(vsEndMin);
			        moEndDate = moEndDate.minute(vsEndMin);
			    }
			    
			    console.log("moDate ::: " + moDate["strTime"] + "/" + moDate["strMin"] + "/" + moDate["endTime"] + "/" + moDate["endMin"]);
			    
			}

